import { useState, useEffect, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Download, ChevronLeft, ChevronRight, Play, X, Circle } from "lucide-react";
import pdf from "../assets/abdul.pdf";

const slides = [
  {
    key: "marsad",
    title: "ERP & WooCommerce Platform (Marsad)",
    summary:
      "Built ERP dashboards and WooCommerce-integrated modules for UAE clients using React.js and Next.js. Developed a custom WordPress plugin to expose a Menu REST API endpoint for headless frontend usage. Delivered scalable UI components with filters, pagination, analytics, and performance improvements.",
    bullets: [
      "Developed responsive ERP dashboards for Orders, Products, Categories, Customers, and Analytics.",
      "Integrated WooCommerce REST APIs for real-time data synchronization.",
      "Built a custom WordPress plugin exposing a Menu REST API endpoint for optimized frontend consumption.",
      "Implemented search, filters, pagination, and stable UI states for production usage.",
      "Improved performance with memoization and optimized API usage patterns."
    ],
    videoSrc: "/videos/marsad.mov"
  },
  {
    key: "swapxe",
    title: "Crypto Dashboard (SwapXe)",
    summary:
      "Developed a secure crypto dashboard with JWT authentication and protected routes. Displayed real-time API results such as wallet and transaction views with a clean, responsive dashboard UI.",
    bullets: [
      "Implemented JWT authentication with secure token handling and route protection.",
      "Integrated APIs to show real-time wallet and transaction-related data.",
      "Built reusable dashboard components and responsive layouts.",
      "Added loading states and error handling for reliable user experience."
    ],
    videoSrc: "/videos/swapxe.mov"
  },
  {
    key: "aviation",
    title: "Aviation ERP (Maintenance & Bug Fixing)",
    summary:
      "Worked on an existing aviation ERP system primarily focused on bug fixing and maintenance. Resolved UI and functional issues and improved stability through better error handling and testing support.",
    bullets: [
      "Fixed UI and functional bugs across ERP screens and workflows.",
      "Resolved API integration issues and improved error handling.",
      "Assisted in validating fixes and reducing recurring production issues."
    ],
    videoSrc: "/videos/aviation_erp.mov"
  },
  {
    key: "blockchain",
    title: "Crypto Exchange (Real-time Quotes & API Integration)",
    summary:
      "Implemented real-time crypto price/quote fetching with external APIs and refresh logic. Focused on reliable data display, API error handling, and performance-friendly UI updates.",
    bullets: [
      "Integrated pricing/quote APIs to show real-time market values.",
      "Implemented refresh logic and safe error handling for unstable APIs.",
      "Optimized UI update flow for smoother performance."
    ],
    videoSrc: "/videos/blockchain.mov"
  },
  {
    key: "jobbot",
    title: "Automation Platform (Job Application Bot + Monitoring)",
    summary:
      "Built a full-stack automation platform with a monitoring dashboard to track bot runs and job application progress. Focused on structured UI, status visibility, and reliable execution feedback.",
    bullets: [
      "Built dashboards to monitor bot runs, statuses, and step-level progress.",
      "Implemented structured logs and clear UI feedback for each run.",
      "Designed the system to process one job at a time for stability."
    ],
    videoSrc: "/videos/jobbot.mov"
  }
];

export default function WorkExperience() {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [direction, setDirection] = useState(0);
  const [selectedVideo, setSelectedVideo] = useState(null);
  const [isPaused, setIsPaused] = useState(false);

  // Auto-advance
  useEffect(() => {
    if (isPaused || selectedVideo) return;
    const timer = setInterval(() => {
      nextSlide();
    }, 7000); // 7s auto-advance (requested 6-8s)
    return () => clearInterval(timer);
  }, [currentSlide, isPaused, selectedVideo]);

  // Lock scroll when modal is open
  useEffect(() => {
    if (selectedVideo) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "unset";
    }
  }, [selectedVideo]);

  // Handle ESC key for modal
  useEffect(() => {
    const handleEsc = (e) => {
      if (e.key === "Escape") setSelectedVideo(null);
    };
    window.addEventListener("keydown", handleEsc);
    return () => window.removeEventListener("keydown", handleEsc);
  }, []);

  const nextSlide = useCallback(() => {
    setDirection(1);
    setCurrentSlide((prev) => (prev + 1) % slides.length);
  }, []);

  const prevSlide = useCallback(() => {
    setDirection(-1);
    setCurrentSlide((prev) => (prev - 1 + slides.length) % slides.length);
  }, []);

  const goToSlide = (index) => {
    setDirection(index > currentSlide ? 1 : -1);
    setCurrentSlide(index);
  };

  const slideVariants = {
    enter: (direction) => ({
      x: direction > 0 ? 1000 : -1000,
      opacity: 0
    }),
    center: {
      zIndex: 1,
      x: 0,
      opacity: 1
    },
    exit: (direction) => ({
      zIndex: 0,
      x: direction < 0 ? 1000 : -1000,
      opacity: 0
    })
  };

  const swipeConfidenceThreshold = 10000;
  const swipePower = (offset, velocity) => {
    return Math.abs(offset) * velocity;
  };

  const current = slides[currentSlide];

  return (
    <motion.section
      id="work-experience"
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.6 }}
      className="max-w-6xl mx-auto px-4 py-16 bg-white dark:bg-gray-900 rounded-xl shadow-xl overflow-hidden"
    >
      <h2 className="text-3xl md:text-4xl font-bold mb-10 text-center text-gray-900 dark:text-white pt-6">
        Work Experience
      </h2>

      {/* Main Carousel Area */}
      <div
        className="relative min-h-[650px] md:min-h-[500px] flex flex-col md:flex-row items-center justify-center p-2 md:p-8"
        onMouseEnter={() => setIsPaused(true)}
        onMouseLeave={() => setIsPaused(false)}
      >
        {/* Navigation Buttons (Absolute) */}
        <button
          onClick={prevSlide}
          className="absolute left-2 top-1/2 -translate-y-1/2 z-20 
            p-3 rounded-full bg-gray-200 dark:bg-gray-800 text-gray-800 dark:text-white 
            hover:bg-gray-300 dark:hover:bg-gray-700 transition shadow-lg"
          aria-label="Previous Slide"
        >
          <ChevronLeft className="w-6 h-6" />
        </button>
        <button
          onClick={nextSlide}
          className="absolute right-2 top-1/2 -translate-y-1/2 z-20 
            p-3 rounded-full bg-gray-200 dark:bg-gray-800 text-gray-800 dark:text-white 
            hover:bg-gray-300 dark:hover:bg-gray-700 transition shadow-lg"
          aria-label="Next Slide"
        >
          <ChevronRight className="w-6 h-6" />
        </button>

        {/* Slide Content Container (AnimatePresence) */}
        <div className="relative w-full h-full flex flex-col md:flex-row shadow-none overflow-hidden">
          <AnimatePresence initial={false} custom={direction}>
            <motion.div
              key={currentSlide}
              custom={direction}
              variants={slideVariants}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{
                x: { type: "spring", stiffness: 300, damping: 30 },
                opacity: { duration: 0.2 }
              }}
              drag="x"
              dragConstraints={{ left: 0, right: 0 }}
              dragElastic={1}
              onDragEnd={(e, { offset, velocity }) => {
                const swipe = swipePower(offset.x, velocity.x);
                if (swipe < -swipeConfidenceThreshold) {
                  nextSlide();
                } else if (swipe > swipeConfidenceThreshold) {
                  prevSlide();
                }
              }}
              className="absolute w-full h-full flex flex-col lg:flex-row items-center lg:items-start gap-8 px-12 md:px-16"
            >

              {/* Left Side: Text Content */}
              <div className="flex-1 text-center lg:text-left order-2 lg:order-1 flex flex-col h-full justify-center">
                <h3 className="text-sm font-bold text-blue-600 uppercase tracking-widest mb-2">
                  Front-End Developer – Numerique360 (Dubai, UAE)
                </h3>
                <h4 className="text-2xl md:text-3xl font-bold text-gray-900 dark:text-white mb-4">
                  {current.title}
                </h4>
                <p className="text-gray-700 dark:text-gray-300 mb-6 leading-relaxed text-base">
                  {current.summary}
                </p>
                <ul className="text-left text-gray-600 dark:text-gray-400 mb-8 space-y-2 list-disc list-inside text-sm md:text-base hidden md:block">
                  {current.bullets.map((item, idx) => (
                    <li key={idx}>{item}</li>
                  ))}
                </ul>

                <div> {/* Button Wrapper */}
                  <a
                    href={pdf}
                    download
                    className="inline-flex items-center gap-2 px-6 py-3 bg-blue-600 text-white rounded-lg shadow 
                      hover:bg-blue-700 transition transform hover:scale-105 font-medium"
                  >
                    <Download className="w-5 h-5" /> Download Resume
                  </a>
                </div>
              </div>

              {/* Right Side: Video Preview */}
              <div className="flex-1 w-full max-w-lg lg:max-w-md order-1 lg:order-2 flex flex-col justify-center">
                <div
                  className="relative w-full rounded-xl overflow-hidden shadow-2xl cursor-pointer group bg-black aspect-video"
                  onClick={() => setSelectedVideo(current.videoSrc)}
                >
                  <div className="absolute inset-0 bg-black/20 group-hover:bg-black/10 transition-colors z-10" />
                  <div className="absolute inset-0 flex items-center justify-center z-20">
                    <div className="bg-white/90 dark:bg-black/80 p-4 rounded-full shadow-xl transform group-hover:scale-110 transition-transform">
                      <Play className="w-8 h-8 text-blue-600 fill-current ml-1" />
                    </div>
                  </div>
                  <video
                    src={current.videoSrc}
                    className="w-full h-full object-cover"
                    muted
                    loop
                    playsInline
                    autoPlay
                    preload="metadata"
                  >
                    <track kind="captions" />
                  </video>
                </div>
                <p className="text-center text-xs text-gray-500 mt-2">
                  If the video doesn’t play, an MP4 version will be provided.
                </p>
              </div>

            </motion.div>
          </AnimatePresence>
        </div>

        {/* Height Spacer (invisible) */}
        <div className="invisible flex flex-col lg:flex-row gap-8 px-12 md:px-16 pointer-events-none w-full">
          <div className="flex-1 text-center lg:text-left flex flex-col">
            <h3 className="text-sm font-bold uppercase tracking-widest mb-2">Role</h3>
            <h4 className="text-2xl md:text-3xl font-bold mb-4">Title Spacer</h4>
            <p className="mb-6 leading-relaxed text-base">Summary Spacer text to keep height consistent.</p>
            <ul className="mb-8 space-y-2 text-sm md:text-base hidden md:block">
              <li>Bullet 1</li>
              <li>Bullet 2</li>
              <li>Bullet 3</li>
              <li>Bullet 4</li>
            </ul>
            <div className="px-6 py-3">Button</div>
          </div>
          <div className="flex-1 w-full max-w-lg lg:max-w-md aspect-video"></div>
        </div>

        {/* Indicators */}
        <div className="flex justify-center gap-3 absolute bottom-2 left-0 right-0 py-4">
          {slides.map((_, idx) => (
            <button
              key={idx}
              onClick={() => goToSlide(idx)}
              className={`transition-all duration-300 p-1 ${idx === currentSlide
                  ? "text-blue-600 scale-125"
                  : "text-gray-400 dark:text-gray-600 hover:text-gray-600 dark:hover:text-gray-400"
                }`}
              aria-label={`Go to slide ${idx + 1}`}
            >
              <Circle className={`w-3 h-3 ${idx === currentSlide ? "fill-current" : ""}`} />
            </button>
          ))}
        </div>
      </div>

      {/* Video Modal */}
      <AnimatePresence>
        {selectedVideo && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4"
            onClick={() => setSelectedVideo(null)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="relative w-full max-w-5xl bg-black rounded-2xl overflow-hidden shadow-2xl"
              onClick={(e) => e.stopPropagation()}
            >
              <button
                onClick={() => setSelectedVideo(null)}
                className="absolute top-4 right-4 p-2 bg-black/50 hover:bg-black/70 text-white rounded-full transition-colors z-10"
              >
                <X className="w-6 h-6" />
              </button>

              <video
                src={selectedVideo}
                controls
                autoPlay
                className="w-full h-auto max-h-[85vh] object-contain mx-auto"
              >
                Your browser does not support the video tag.
              </video>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.section>
  );
}
